fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Vec<Vec<i8>> {
    // shape has length 2 by problem statement
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // Length of input array
    let len = a.len();

    // By assumption, len == r or len == c

    // Result matrix: Vec of r rows, each with c elements
    let mut matrix = Vec::with_capacity(r);

    if len == r {
        // Treat `a` as a column vector:
        // each row i is a[i] repeated c times
        for i in 0..r {
            // replicate a[i] c times
            let row_value = a[i];
            let row = vec![row_value; c];
            matrix.push(row);
        }
    } else {
        // Otherwise, len == c; treat `a` as a row vector:
        // every row is a clone of input array `a`
        for _ in 0..r {
            matrix.push(a.clone());
        }
    }

    matrix
}